import{z as l,x as B,o as r,c as d,q as A,j as o,D as E,d as t,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"复位策略","description":"","frontmatter":{"title":"复位策略","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/reset-strategy.md","filePath":"cs/reset-strategy.md","lastUpdated":1791063341000}'),F={name:"cs/reset-strategy.md"};function p(D,a,c,m,u,h){const s=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=A('<h1 id="复位策略" tabindex="-1">复位策略 <a class="header-anchor" href="#复位策略" aria-label="Permalink to &quot;复位策略&quot;">​</a></h1><div class="epigraph"><p>复位要让状态机进已知态，但释放沿必须相对于时钟可预测：异步断言、同步释放是常见折中，否则恢复时间与偏斜会在上电时制造幽灵状态。</p><footer>—— 据 Cummings, Synthesizable Finite State Machine Design Techniques Using the New SystemVerilog 3.0, SNUG；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p><a href="/cs/clock-skew-cts">上一课</a>让每个 FF 的时钟到达时间变成数字。复位是另一根全局网：它也要树，也有偏斜。缺口是<strong>复位策略</strong>——异步还是同步、如何释放——否则 STA 的恢复/移除检查与上电行为对不齐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>异步复位：<code>always @(posedge clk or negedge rst_n)</code>，断言立刻清 Q，不依赖时钟，上电友好。释放时 <code>rst_n</code> 相对 <code>clk</code> 若落在恢复窗口，FF 亚稳——与<a href="/cs/setup-hold">建立保持</a>同类窗口，名字叫 recovery/removal。同步复位：只在边沿采样复位，释放自然对齐时钟，但断言也要等时钟，时钟未振时清不掉。缺口不是再讲 CTS，而是这两类复位如何接、如何把释放同步化。</p><p>常用：异步断言、经两级 FF <strong>同步释放</strong>，再送到各异步复位脚。复位树同样要 CTS 一类平衡。</p><h3 id="每个寄存器都异步复位不是免费" tabindex="-1">每个寄存器都异步复位不是免费 <a class="header-anchor" href="#每个寄存器都异步复位不是免费" aria-label="Permalink to &quot;每个寄存器都异步复位不是免费&quot;">​</a></h3><p>面积、布线、复位树功耗、以及「故意不复位」的流水线数据寄存器（下一拍会被有效数据覆盖）。全芯片异步复位会让综合插入大量复位端口。把「好设计=处处复位」当成教条，时序与布线会胀。</p><p><span class="marginnote">Cummings 的 FSM 与复位风格文章是 RTL 实践来源。Harris 给出异步复位模板。本课不把上电复位芯片内部模拟电路画完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>外部 <code>rst_n</code> 异步来。同步器（两级 FF，时钟已稳定后）产生内部 <code>rst_n_sync</code>。消费端：异步复位脚接 <code>rst_n_sync</code>，释放已与时钟同源。需要完全同步复位的路径只用数据端 MUX。扫描测试时复位可被 DFT 改接，后课扫描链再钉。</p>',11)),(r(),o(i,null,{default:E(()=>[n(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXT%5B%22%E5%A4%96%E9%83%A8%E5%A4%8D%E4%BD%8D%22%5D%20--%3E%20SYNC%5B%22%E4%B8%A4%E7%BA%A7%E5%90%8C%E6%AD%A5%E9%87%8A%E6%94%BE%22%5D%0A%20%20SYNC%20--%3E%20FF%5B%22FF%20%E5%BC%82%E6%AD%A5%E5%A4%8D%E4%BD%8D%E8%84%9A%22%5D%0A%20%20FF%20--%3E%20FSM%5B%22%E5%B7%B2%E7%9F%A5%E5%88%9D%E6%80%81%22%5D%0A%20%20SYNC%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%B7%A8%E6%97%B6%E9%92%9F%E5%9F%9F%20FIFO%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"多时钟域：每个域自己同步释放，不要把 A 域已释放的复位直接异步灌进 B 域。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：「异步断言、同步释放」就是「拉复位可以随时（不等时钟），放开复位必须挑时钟说好的时刻」。可以想象成拉闸断电随便哪秒都行，但重新合闸必须由钟表匠按表操作——否则各 FF 有的已经「醒来」、有的还在复位，机器上电就进入半死不活的状态。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"为什么重要：释放沿若落在恢复/移除窗口，部分 FF 脱离复位、部分仍在，状态机可能进非法编码态且此后再不复位也无法纠正。这类故障只在几百 ppm 的概率上出现，常温测试正常、高低温老化偶发——是最难在板级复现的一类数字病。")],-1)),a[6]||(a[6]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=e("p",null,"下一课异步 FIFO 处理数据跨域；复位跨域同样要按域同步，否则 FIFO 指针的初值在两边不是「同时」变零。STA：声明复位为时序检查对象（recovery），或把异步复位路径设为假路径并依赖同步释放结构——约束必须匹配 RTL。",-1)),(r(),o(i,null,{default:E(()=>[n(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%BA%AF%E5%BC%82%E6%AD%A5%E5%A4%8D%E4%BD%8D%3A%20%E6%96%AD%E8%A8%80%E9%87%8A%E6%94%BE%E9%83%BD%E4%B8%8D%E7%9C%8B%E6%97%B6%E9%92%9F%22%5D%20--%3E%20F1%5B%22%E4%B8%8A%E7%94%B5%E5%BF%AB%2C%20%E4%BD%86%E9%87%8A%E6%94%BE%E6%B2%BF%E5%8F%AF%E8%83%BD%E6%92%9E%E6%81%A2%E5%A4%8D%E7%AA%97%E5%8F%A3%22%5D%0A%20%20B%5B%22%E7%BA%AF%E5%90%8C%E6%AD%A5%E5%A4%8D%E4%BD%8D%3A%20%E9%87%8A%E6%94%BE%E8%87%AA%E7%84%B6%E5%AF%B9%E9%BD%90%22%5D%20--%3E%20F2%5B%22%E6%97%B6%E9%92%9F%E6%9C%AA%E6%8C%AF%E6%97%B6%E6%B8%85%E4%B8%8D%E6%8E%89%2C%20%E4%B8%8A%E7%94%B5%E4%B8%8D%E5%8F%AF%E9%9D%A0%22%5D%0A%20%20C%5B%22%E5%BC%82%E6%AD%A5%E6%96%AD%E8%A8%80%20%2B%20%E4%B8%A4%E7%BA%A7FF%E5%90%8C%E6%AD%A5%E9%87%8A%E6%94%BE%22%5D%20--%3E%20G%5B%22%E4%B8%8A%E7%94%B5%E5%8F%AF%E9%9D%A0%E4%B8%94%E9%87%8A%E6%94%BE%E5%8F%AF%E9%A2%84%E6%B5%8B%22%5D%0A%20%20F1%20-.%E6%8A%98%E4%B8%AD.-%3E%20G%0A%20%20F2%20-.%E6%8A%98%E4%B8%AD.-%3E%20G%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=A('<p>这张图回答的问题是「两类复位各坏在哪、为什么工程上取中间路线」：纯异步输在释放沿不可预测，纯同步输在时钟没跑起来时无法断言；两级 FF 同步释放让断言享受即时性、释放享受确定性，代价只是两个触发器。</p><p><span class="marginnote">常见误区：初学者容易给每个寄存器都接异步复位以为「更安全」。实际上流水线中间的数据寄存器，哪怕上电是垃圾值，下一拍就会被有效数据覆盖；处处复位徒增复位树的面积、布线与功耗——「不复位」有时是刻意的正确设计。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲上电复位（POR）带隙电路，不把看门狗当成复位策略的全部。不讨论部分复位（只复位外设子系统）的电源域细节，留给后课功耗/电源。</p><p>后课默认：复位异步断言、同步释放；每时钟域各有同步后的复位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>异步断言方便上电；释放必须相对时钟过恢复窗口。</li><li>两级同步释放是常用结构；复位树也有偏斜。</li><li>跨域复位与跨域数据一样要同步。</li><li>出处：Cummings SNUG；Harris and Harris。</li></ul>',7))])}const _=l(F,[["render",p]]);export{C as __pageData,_ as default};
